from pathlib import Path
import bpy,json,hashlib
W=Path(__file__).resolve().parent;R=W.parents[2];P=json.load(open(W/'UPPER_OPERATION_PLAN.json'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def fingerprint(o):return {'matrix':[list(x)for x in o.matrix_world],'vertices':[list(v.co)for v in o.data.vertices],'faces':[list(p.vertices)for p in o.data.polygons],'uv':[[list(x.uv)for x in u.data]for u in o.data.uv_layers],'materials':[m.name for m in o.data.materials]}
results=[]
for spec in P['receiving_reconciliations']:
 source=R/spec['old_native'];assert sha(source)==P['source_pins'][spec['old_native']];bpy.ops.wm.open_mainfile(filepath=str(source));closure=bpy.data.objects[spec['closure_mesh']];before={o.name:fingerprint(o)for o in bpy.context.scene.objects if o.type=='MESH'and o!=closure};removed=fingerprint(closure);bpy.data.objects.remove(closure,do_unlink=True);native=W/spec['new_native'];export=W/spec['new_export'];bpy.ops.wm.save_as_mainfile(filepath=str(native));bpy.ops.export_scene.gltf(filepath=str(export),export_format='GLB',export_extras=True);h=sha(export);bpy.ops.wm.open_mainfile(filepath=str(native));assert all(fingerprint(bpy.data.objects[n])==f for n,f in before.items());assert len(before)==spec['old_mesh_count']-1;bpy.ops.export_scene.gltf(filepath=str(export),export_format='GLB',export_extras=True);assert sha(export)==h;results.append({'deck':spec['deck'],'native':native.name,'native_sha256':sha(native),'export':export.name,'export_sha256':h,'unchanged_meshes':len(before),'fresh_native_repeat_identical':True,'removed_whole_mesh':spec['closure_mesh'],'removed_geometry_fingerprint_sha256':hashlib.sha256(json.dumps(removed,sort_keys=True).encode()).hexdigest()})
(W/'NATIVE_EXPORT_CHECK.json').write_text(json.dumps({'status':'PASS','blender_version':bpy.app.version_string,'receiving_successors':results,'original_assets_unchanged':True},indent=2)+'\n');print('UPPER_OPERATION_NATIVE_PASS',json.dumps(results))
